sys_script_include.script:
var AggregateApiService = Class.create();

// aggregate -> [table key, lookup columns tried after sys_id]
AggregateApiService.LOOKUP = {
    submission: ['SUBMISSION', ['number', 'external_id']],
    quote: ['QUOTE', ['number', 'quote_number']],
    policy: ['POLICY', ['policy_number', 'number', 'external_ref']],
    policy_version: ['POLICY_VERSION', ['number', 'external_ref']],
    product: ['PRODUCT', ['product_code']]
};

AggregateApiService.prototype = {

    initialize: function () {
        this.serializer = new AggregateSerializer();
    },

    // GET /aggregate/{type}/{id}[?format=acord]
    getAggregate: function (request) {
        var type = String(request.pathParams.type || '');
        if (!AggregateApiService.LOOKUP[type])
            return this._error(400, 'ERRORV2-001', 'Unknown aggregate "' + type + '". Use one of: ' + Object.keys(AggregateApiService.LOOKUP).join(', '));
        var sysId = this._resolve(type, String(request.pathParams.id || ''));
        if (!sysId)
            return this._error(404, 'ERRORV2-404', type + ' ' + request.pathParams.id + ' not found');
        var doc = this.serializer.serialize(type, sysId);
        if (this._param(request, 'format') === 'acord')
            return { _status: 200, _raw: new AcordRenderer().render(type, doc), _contentType: 'application/xml' };
        doc._status = 200;
        return doc;
    },

    // GET /policy/{number}/version[?as_of=yyyy-mm-dd]
    getPolicyVersion: function (request) {
        var provider = new IntegrationRegistry().getProvider('policy');
        var number = String(request.pathParams.number || '');
        var policy = provider.getPolicy ? provider.getPolicy(number) : null;
        if (!policy)
            return this._error(404, 'ERRORV2-404', 'Policy ' + number + ' not found');
        var asOf = this._param(request, 'as_of');
        if (asOf && !/^\d{4}-\d{2}-\d{2}$/.test(asOf))
            return this._error(400, 'ERRORV2-002', 'as_of must be yyyy-mm-dd');
        var version = provider.getCurrentVersion(policy.getUniqueValue(), asOf || '');
        if (!version)
            return this._error(404, 'ERRORV2-404', 'No version of ' + number + (asOf ? ' in force on ' + asOf : ''));
        var doc = this.serializer.serialize('policy_version', version.getUniqueValue());
        doc._status = 200;
        return doc;
    },

    // GET /schema/{code} - the contract published to the AI pipeline and integrators
    getSchema: function (request) {
        var code = String(request.pathParams.code || '');
        var sd = new GlideRecord(Constants.TABLE.SCHEMA_DEFINITION);
        sd.addQuery('code', code);
        sd.addQuery('status', Constants.CHOICE.CATALOG_STATUS.PUBLISHED);
        sd.orderByDesc('version');
        sd.setLimit(1);
        sd.query();
        if (!sd.next())
            return this._error(404, 'ERRORV2-404', 'No published schema ' + code);
        var nodes = [];
        var n = new GlideRecord(Constants.TABLE.SCHEMA_NODE);
        n.addQuery('schema_definition', sd.getUniqueValue());
        n.orderBy('display_order');
        n.query();
        while (n.next()) {
            nodes.push({ path: String(n.path), name: String(n.name), data_type: String(n.data_type), cardinality: String(n.cardinality),
                repeating: String(n.is_repeating) === 'true', table: String(n.table_name || ''), column: String(n.column_name || ''),
                sample: String(n.sample_value || ''), description: String(n.description || '') });
        }
        return { _status: 200, code: code, version: String(sd.version), format: String(sd.format), role: String(sd.schema_role),
            description: String(sd.description || ''), nodes: nodes };
    },

    // POST /mapping/{code}/transform - simulation, never writes
    transform: function (request) {
        var body = request.body ? request.body.data : null;
        if (!body || typeof body !== 'object')
            return this._error(400, 'ERRORV2-003', 'Request body must be the source JSON document');
        var res = new MappingEngine().transform(String(request.pathParams.code || ''), body);
        if (!res.mapping)
            return this._error(404, 'ERRORV2-404', res.errors.join('; '));
        return { _status: 200, mapping: res.mapping, rows: res.rows, errors: res.errors };
    },

    // POST /event - inbox. Body: { event_type, correlation_id, aggregate?, system?, table?, record?, payload }
    receiveEvent: function (request) {
        var b = request.body ? request.body.data : null;
        if (!b || !b.event_type)
            return this._error(400, 'ERRORV2-004', 'event_type is mandatory');
        if (!b.correlation_id)
            return this._error(400, 'ERRORV2-005', 'correlation_id is mandatory');
        var systemId = '';
        if (b.system) {
            var s = new GlideRecord(Constants.TABLE.INTEGRATION_SYSTEM);
            s.addQuery('code', String(b.system));
            s.setLimit(1);
            s.query();
            if (!s.next())
                return this._error(400, 'ERRORV2-006', 'Unknown integration system ' + b.system);
            systemId = s.getUniqueValue();
        }
        var res = new IntegrationEventPublisher().receive({
            eventType: String(b.event_type), aggregate: b.aggregate ? String(b.aggregate) : '', table: b.table ? String(b.table) : '',
            sysId: b.record ? String(b.record) : '', system: systemId, correlationId: String(b.correlation_id), payload: b.payload === undefined ? {} : b.payload
        });
        var ev = new GlideRecord(Constants.TABLE.INTEGRATION_EVENT);
        ev.get(res.sys_id);
        return {
            _status: res.duplicate ? 200 : 201,
            _location: '/api/now/table/' + Constants.TABLE.INTEGRATION_EVENT + '/' + res.sys_id,
            sys_id: res.sys_id, number: String(ev.number), status: String(ev.status), duplicate: res.duplicate
        };
    },

    _resolve: function (type, id) {
        var cfg = AggregateApiService.LOOKUP[type];
        var table = Constants.TABLE[cfg[0]];
        var gr = new GlideRecord(table);
        if (/^[0-9a-f]{32}$/.test(id) && gr.get(id))
            return gr.getUniqueValue();
        for (var i = 0; i < cfg[1].length; i++) {
            var q = new GlideRecord(table);
            q.addQuery(cfg[1][i], id);
            if (type === 'product')
                q.orderByDesc('version');
            q.setLimit(1);
            q.query();
            if (q.next())
                return q.getUniqueValue();
        }
        return '';
    },

    _param: function (request, name) {
        var v = request.queryParams ? request.queryParams[name] : null;
        if (v && v.length !== undefined && typeof v !== 'string')
            v = v[0];
        return v ? String(v) : '';
    },

    _error: function (status, code, message) {
        return { _status: status, error: { code: code, message: message } };
    },

    type: 'AggregateApiService'
};
